examples.source:
import Listbox from "@marko-ui/shadcn/ui/listbox/listbox.marko";

static const fruits = [
  { value: "apple", label: "Apple" },
  { value: "banana", label: "Banana" },
  { value: "blueberry", label: "Blueberry" },
  { value: "grapes", label: "Grapes" },
  { value: "pineapple", label: "Pineapple" },
];

<Listbox items=fruits label="Favorite fruit" defaultValue=["apple"]/>

import Listbox from "@marko-ui/shadcn/ui/listbox/listbox.marko";

static const fruits = [
  { value: "apple", label: "Apple" },
  { value: "banana", label: "Banana" },
  { value: "blueberry", label: "Blueberry" },
  { value: "grapes", label: "Grapes" },
  { value: "pineapple", label: "Pineapple" },
];

<Listbox items=fruits label="Fruits" selectionMode="multiple" defaultValue=["apple", "grapes"]/>

import Listbox from "@marko-ui/shadcn/ui/listbox/listbox.marko";

static const fruitsWithDisabled = [
  { value: "apple", label: "Apple" },
  { value: "banana", label: "Banana", disabled: true },
  { value: "blueberry", label: "Blueberry" },
  { value: "grapes", label: "Grapes", disabled: true },
  { value: "pineapple", label: "Pineapple" },
];

<Listbox items=fruitsWithDisabled label="Favorite fruit" defaultValue=["apple"]/>
